import React, { useEffect, useState } from 'react'

import NewsItem from './NewsItem'
import Spinner from './Spinner';
import Skeleton from './Skeleton';
import PropTypes from 'prop-types'
import InfiniteScroll from "react-infinite-scroll-component";
import sampleOutput from '../sampleOutput.json';

const News = (props) => {
    const [articles, setArticles] = useState([])
    const [loading, setLoading] = useState(true)
    const [errorMessage, setErrorMessage] = useState(null)
    const [nextPage, setNextPage] = useState(null)
    const [totalResults, setTotalResults] = useState(0)
    const appLogo = `${process.env.PUBLIC_URL}/logo.png`;

    const capitalizeFirstLetter = (string) => {
        return string.charAt(0).toUpperCase() + string.slice(1);
    }

    const buildNewsDataUrl = (pageToken = null) => {
        const params = new URLSearchParams({
            apikey: props.apiKey,
            country: props.country,
        });

        // If search query exists, use it. Otherwise use category.
        if (props.searchQuery) {
            params.append('q', props.searchQuery);
        } else {
            // Map 'general' to 'top' as 'general' is not supported by newsdata.io
            const categoryParam = props.category === 'general' ? 'top' : props.category;
            params.append('category', categoryParam);
        }

        if (props.language) {
            params.append('language', props.language);
        }
        if (pageToken) {
            params.append('page', pageToken);
        }
        return `https://newsdata.io/api/1/news?${params.toString()}`;
    }

    const fetchPage = async (pageToken = null) => {
        if (!pageToken) {
            props.setProgress(10);
            setLoading(true);
        }

        const url = buildNewsDataUrl(pageToken);
        setErrorMessage(null)

        try {
            let data = await fetch(url);
            if (!pageToken) props.setProgress(30);

            if (data.status === 429 || data.status === 402) {
                throw new Error("Rate limit exceeded");
            }

            if (!data.ok) {
                const errorBody = await data.json().catch(() => ({}));
                const message = errorBody.results?.message || `Unable to load news (status ${data.status})`;
                throw new Error(message);
            }

            let parsedData = await data.json()
            if (!pageToken) props.setProgress(70);

            setArticles(prevArticles => pageToken ? prevArticles.concat(parsedData.results || []) : (parsedData.results || []));
            setNextPage(parsedData.nextPage || null)
            setTotalResults(parsedData.totalResults || 0)

        } catch (error) {
            if (!pageToken) {
                // Fallback to mock data on rate limit or other errors
                if (error.message.includes("Rate limit") || error.message.includes("429")) {
                    setArticles(sampleOutput.results);
                    setTotalResults(sampleOutput.totalResults);
                    setNextPage(null); // Disable infinite scroll for mock data
                    setErrorMessage("API Rate Limit Exceeded. Displaying MOCK DATA for demonstration.");
                } else {
                    setArticles([])
                    setErrorMessage(error.message || 'Unable to load news at the moment.')
                }
            }
        } finally {
            setLoading(false)
            if (!pageToken) props.setProgress(100);
        }
    }

    useEffect(() => {
        const titleCategory = props.searchQuery ? `Search: ${props.searchQuery}` : capitalizeFirstLetter(props.category);
        document.title = `${titleCategory} - NewsMonkey`;
        fetchPage(null);
        // eslint-disable-next-line
    }, [props.category, props.country, props.language, props.searchQuery])

    const fetchMoreData = () => {
        if (nextPage) {
            fetchPage(nextPage);
        }
    };

    return (
        <div className="retro-app-container">
            <div className="headline-banner text-center">
                <img
                    src={appLogo}
                    alt="NewsMonkey logo"
                    className="news-logo"
                />
                <h1 className="retro-text-amber headline-title">
                    {props.searchQuery
                        ? `Search Results for: "${props.searchQuery}"`
                        : `NewsMonkey - Top ${capitalizeFirstLetter(props.category)} Headlines`
                    }
                    {totalResults > 0 && <span style={{ fontSize: '0.6em', display: 'block', marginTop: '5px', opacity: 0.8 }}>[{totalResults} RECORDS FOUND]</span>}
                </h1>
            </div>

            {errorMessage && (
                <div
                    className="alert retro-alert-danger text-center"
                    role="alert"
                    style={{
                        margin: '20px auto',
                        width: 'fit-content',
                        border: '2px dashed #ffb700',
                        backgroundColor: 'black',
                        color: '#ffb700',
                        textShadow: '0 0 3px #ffb700'
                    }}
                >
                    &gt;&gt; FATAL_ERROR: {errorMessage}
                </div>
            )}

            <InfiniteScroll
                dataLength={articles.length}
                next={fetchMoreData}
                hasMore={nextPage !== null}
                loader={<Spinner />}
                endMessage={
                    <p style={{ textAlign: 'center', color: 'var(--amber)', marginTop: '20px' }}>
                        <b>&gt;&gt; END_OF_STREAM: No more articles to load.</b>
                    </p>
                }
            >
                <div className="container">
                    <div className="row">
                        {loading && articles.length === 0 && [1, 2, 3, 4, 5, 6].map(n => <Skeleton key={n} />)}

                        {articles.map((element, index) => {
                            const key = element.link || element.url || element.title || index;
                            return <div className="col-md-4" key={key}>
                                <NewsItem
                                    title={element.title ? element.title : "[[NO TITLE DATA]]"}
                                    description={element.description ? element.description.slice(0, 88) + "..." : "[[NO DESCRIPTION DATA]]"}
                                    imageUrl={element.image_url || element.urlToImage}
                                    newsUrl={element.link || element.url}
                                    author={element.creator ? element.creator.join(', ') : element.author || "Unknown User"}
                                    date={element.pubDate || element.publishedAt}
                                    source={element.source_id || element.source?.name || "Unknown Source"}
                                    retroStyle="amber"
                                />
                            </div>
                        })}
                    </div>
                </div>
            </InfiniteScroll>
        </div>
    )
}


News.defaultProps = {
    country: 'in',
    pageSize: 8,
    category: 'general',
    language: 'en',
    searchQuery: ''
}

News.propTypes = {
    country: PropTypes.string,
    pageSize: PropTypes.number,
    category: PropTypes.string,
    language: PropTypes.string,
    apiKey: PropTypes.string.isRequired,
    setProgress: PropTypes.func.isRequired,
    searchQuery: PropTypes.string
}

export default News