import './App.css';

import React, { useEffect, useState } from 'react'
import NavBar from './components/NavBar';
import News from './components/News';
import { BrowserRouter as Router, Switch, Route } from "react-router-dom";
import LoadingBar from 'react-top-loading-bar'

const App = () => {

  const pageSize = 5;
  const apiKey = process.env.REACT_APP_NEWS_API;   // <-- Correct place

  const [progress, setProgress] = useState(0);
  const [theme, setTheme] = useState('dark');
  const [searchQuery, setSearchQuery] = useState("");

  useEffect(() => {
    document.body.dataset.theme = theme;
  }, [theme]);

  const toggleTheme = () => {
    setTheme((prev) => prev === 'dark' ? 'light' : 'dark');
  };

  const handleSearch = (query) => {
    setSearchQuery(query);
  };

  const getBasePath = () => {
    if (!process.env.PUBLIC_URL) {
      return '/';
    }
    try {
      const url = new URL(process.env.PUBLIC_URL, window.location.origin);
      return url.pathname || '/';
    } catch (error) {
      return '/';
    }
  };

  return (
    <div>
      <Router basename={getBasePath()}>
        <NavBar theme={theme} onToggleTheme={toggleTheme} onSearch={handleSearch} resetSearch={() => setSearchQuery("")} />
        <LoadingBar
          height={3}
          color='#f11946'
          progress={progress}
        />
        <Switch>
          <Route exact path="/">
            <News setProgress={setProgress} apiKey={apiKey} key={`general-${searchQuery}`} pageSize={pageSize} country="in" category="general" searchQuery={searchQuery} />
          </Route>

          <Route exact path="/business">
            <News setProgress={setProgress} apiKey={apiKey} key={`business-${searchQuery}`} pageSize={pageSize} country="in" category="business" searchQuery={searchQuery} />
          </Route>

          <Route exact path="/entertainment">
            <News setProgress={setProgress} apiKey={apiKey} key={`entertainment-${searchQuery}`} pageSize={pageSize} country="in" category="entertainment" searchQuery={searchQuery} />
          </Route>

          <Route exact path="/general">
            <News setProgress={setProgress} apiKey={apiKey} key={`general2-${searchQuery}`} pageSize={pageSize} country="in" category="general" searchQuery={searchQuery} />
          </Route>

          <Route exact path="/health">
            <News setProgress={setProgress} apiKey={apiKey} key={`health-${searchQuery}`} pageSize={pageSize} country="in" category="health" searchQuery={searchQuery} />
          </Route>

          <Route exact path="/science">
            <News setProgress={setProgress} apiKey={apiKey} key={`science-${searchQuery}`} pageSize={pageSize} country="in" category="science" searchQuery={searchQuery} />
          </Route>

          <Route exact path="/sports">
            <News setProgress={setProgress} apiKey={apiKey} key={`sports-${searchQuery}`} pageSize={pageSize} country="in" category="sports" searchQuery={searchQuery} />
          </Route>

          <Route exact path="/technology">
            <News setProgress={setProgress} apiKey={apiKey} key={`technology-${searchQuery}`} pageSize={pageSize} country="in" category="technology" searchQuery={searchQuery} />
          </Route>
        </Switch>
      </Router>
    </div>
  );
}

export default App;
